<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue';
import {useApp} from '../stores/app';import {exercises,muscles,findExercise} from '../core/exercises';
import {equipmentGroups,homeEquipment,matchesEquipment,sameMuscle,replaceExercise} from '../core/catalog';
import Icon from '../components/Icon.vue';import MuscleBody from '../components/MuscleBody.vue';import ExerciseImage from '../components/ExerciseImage.vue';
import {remaining,timeLabel} from '../core/logic';import type {Exercise} from '../core/models';
const windowConfirm=window.confirm.bind(window);const windowScrollTop=()=>window.scrollTo({top:0,behavior:'instant'});
const app=useApp();
const tab=ref<'explore'|'builder'|'saved'>('explore'),search=ref(''),muscle=ref('All muscles'),equipment=ref('All equipment'),onlyFav=ref(false);
const location=ref('all'),available=ref(['Dumbbells']),altLocation=ref('all'),altEquipment=ref('All equipment');
const alternatives=computed(()=>detail.value?exercises.filter(e=>sameMuscle(detail.value!,e)&&matchesEquipment(e,altLocation.value,altEquipment.value,available.value)).sort((a,b)=>Number(b.pattern===detail.value!.pattern)-Number(a.pattern===detail.value!.pattern)):[]);
function replaceWith(id:string){if(!detail.value)return;selected.value=replaceExercise(selected.value,detail.value.id,id);msg.value='Exercise replaced in your workout draft.';detail.value=null;}
const selected=ref<string[]>([...(app.data.workoutDraft?.exerciseIds||[])]),routineName=ref(app.data.workoutDraft?.name||'My workout');
const detail=ref<Exercise|null>(null),dialog=ref<HTMLDialogElement|null>(null),selectedExercise=ref(app.active?.exerciseIds[0]||''),reps=ref(10),kg=ref(0),restSeconds=ref(60),msg=ref(''),busy=ref(false),now=ref(Date.now());
const finishDialog=ref<HTMLDialogElement|null>(null),discardDialog=ref<HTMLDialogElement|null>(null);let timer:ReturnType<typeof setInterval>;
onMounted(()=>{timer=setInterval(()=>now.value=Date.now(),1000);});onUnmounted(()=>clearInterval(timer));
watch(detail,async value=>{if(value){await nextTick();if(dialog.value&&!dialog.value.open)dialog.value.showModal();dialog.value?.scrollTo({top:0});}});
watch([selected,routineName],()=>{app.data.workoutDraft={name:routineName.value,exerciseIds:[...selected.value]};app.save().catch(()=>{});},{deep:true});
watch(selectedExercise,id=>{const last=[...app.data.sessions].sort((a,b)=>b.start-a.start).flatMap(s=>[...s.sets].reverse()).find(s=>s.exerciseId===id);reps.value=last?.reps||10;kg.value=last?.kg||0;},{immediate:true});
const filtered=computed(()=>exercises.filter(e=>(muscle.value==='All muscles'||e.muscle===muscle.value)&&matchesEquipment(e,location.value,equipment.value,available.value)&&(`${e.name} ${e.muscle} ${e.equipment}`).toLowerCase().includes(search.value.toLowerCase())&&(!onlyFav.value||app.data.favorites.includes(e.id))));
const current=computed(()=>findExercise(selectedExercise.value));const position=computed(()=>app.active?.exerciseIds.indexOf(selectedExercise.value)??0);
const currentSets=computed(()=>app.active?.sets.filter(s=>s.exerciseId===selectedExercise.value)||[]);
const rest=computed(()=>app.active?.pausedRest??remaining(app.active?.restEnd??null,now.value));
const untouched=computed(()=>app.active?.exerciseIds.filter(id=>!app.active!.sets.some(s=>s.exerciseId===id)).length||0);
async function attempt(fn:()=>Promise<unknown>){if(busy.value)return;busy.value=true;msg.value='';try{await fn();}catch(e){msg.value=e instanceof Error?e.message:'Unable to save.';}finally{busy.value=false;}}
function toggle(id:string){const removing=selected.value.includes(id);selected.value=removing?selected.value.filter(x=>x!==id):[...selected.value,id];msg.value=removing?'Exercise removed from your workout.':`${findExercise(id).name} added to your workout.`;}
async function favorite(id:string){app.data.favorites=app.data.favorites.includes(id)?app.data.favorites.filter(x=>x!==id):[...app.data.favorites,id];await app.save();}
async function start(){if(!selected.value.length)return;await app.start(selected.value,routineName.value.trim()||'My workout');selectedExercise.value=app.active?.exerciseIds[0]||'';window.scrollTo({top:0,behavior:'instant'});}
async function restAction(action:string){const s=app.active;if(!s)return;if(action==='skip'){s.restEnd=null;s.pausedRest=null;}else if(action==='add'){if(s.pausedRest!==null)s.pausedRest+=30;else s.restEnd=Math.max(Date.now(),s.restEnd||0)+30000;}else if(s.pausedRest!==null){s.restEnd=Date.now()+s.pausedRest*1000;s.pausedRest=null;}else{s.pausedRest=remaining(s.restEnd);s.restEnd=null;}await app.save();}
async function saveRoutine(){app.data.routines.push({id:crypto.randomUUID(),name:routineName.value.trim()||'My workout',exerciseIds:[...selected.value]});await app.save();msg.value='Routine saved. You can find it in Saved routines.';}
function move(i:number,delta:number){if(i+delta<0||i+delta>=selected.value.length)return;const items=[...selected.value];[items[i],items[i+delta]]=[items[i+delta]!,items[i]!];selected.value=items;}
function resetFilters(){search.value='';muscle.value='All muscles';equipment.value='All equipment';location.value='all';onlyFav.value=false;}
function nextExercise(delta:number){const id=app.active?.exerciseIds[position.value+delta];if(id)selectedExercise.value=id;}
async function discard(){discardDialog.value?.close();const id=app.active?.id;app.data.sessions=app.data.sessions.filter(s=>s.id!==id);await app.save();msg.value='Session discarded. Your saved routines are still available.';}
async function finish(){finishDialog.value?.close();await app.finish();msg.value='Workout completed and saved. See your results in Progress.';}
</script>
<template>
<div class="train-page" :class="{'has-selection':selected.length&&!app.active}">
<section class="page-heading"><div><div class="eyebrow">YOUR TRAINING SPACE</div><h1>{{app.active?'Let’s train.':'Find your next'}} <span v-if="!app.active">movement.</span></h1><p>{{app.active?'Follow the two positions, log your set, then take a rest.':'See how it moves. Add it to your workout. Train at your pace.'}}</p></div><RouterLink v-if="app.active" to="/progress" class="button secondary">View history<Icon name="ChartNoAxesCombined" :size="17"/></RouterLink><span v-else class="pill"><Icon name="Check" :size="16"/>{{exercises.length}} visual exercise guides</span></section>
<p v-if="msg" class="notice" role="status">{{msg}}<button class="icon-button" aria-label="Dismiss message" @click="msg=''"><Icon name="X" :size="17"/></button></p>
<template v-if="app.active">
<section class="session-strip"><div><span class="eyebrow">{{app.active.name}}</span><strong>Exercise {{position+1}} <span>of {{app.active.exerciseIds.length}}</span></strong></div><div class="session-strip-stats"><span><Icon name="Clock" :size="16"/>{{timeLabel(Math.max(0,(now-app.active.start)/1000))}}</span><span><Icon name="Check" :size="16"/>{{app.active.sets.length}} sets logged</span></div><button class="button secondary" @click="finishDialog?.showModal()" :disabled="!app.active.sets.length">Finish workout</button></section>
<div class="training-session-grid"><section class="card session-movement"><div class="session-exercise-nav"><button class="icon-button" aria-label="Previous exercise" :disabled="position===0" @click="nextExercise(-1)"><Icon name="ArrowLeft"/></button><label class="visually-hidden" for="current-exercise">Current exercise</label><select id="current-exercise" v-model="selectedExercise"><option v-for="id in app.active.exerciseIds" :key="id" :value="id">{{findExercise(id).name}}</option></select><button class="icon-button" aria-label="Next exercise" :disabled="position===app.active.exerciseIds.length-1" @click="nextExercise(1)"><Icon name="ArrowRight"/></button></div><div v-if="current" class="movement-title"><span class="pill">{{current.muscle}} · {{current.equipment}}</span><h2>{{current.name}}</h2></div><ExerciseImage v-if="current" :exercise-id="current.id" :name="current.name"/></section>
<div class="session-controls"><section class="card set-entry"><div class="section-title"><h3>Log your set</h3><span class="pill">SET {{currentSets.length+1}}</span></div><p class="muted">Enter what you actually completed.</p><form @submit.prevent="attempt(async()=>{await app.addSet(selectedExercise,reps,kg,restSeconds);msg='Set saved. Take your rest.'})"><div class="form-grid"><label>Repetitions<input v-model.number="reps" inputmode="numeric" type="number" min="1" max="500" step="1" required></label><label>Total weight (kg)<input v-model.number="kg" inputmode="decimal" type="number" min="0" max="1000" step="0.5" required></label></div><p class="input-help">{{current?.equipmentGroup==='Machines'||current?.equipmentGroup==='Cable'?'Record the stack label; compare loads only on the same machine.':current?.equipmentGroup==='Resistance bands'?'Use 0 kg when band resistance is not measured.':current?.equipmentGroup==='Barbell'?'Include the bar and all plates in the total.':'Two 5 kg dumbbells = 10 kg total. Bodyweight = 0 kg.'}}</p><label>Rest after this set<select v-model.number="restSeconds"><option :value="30">30 seconds</option><option :value="60">60 seconds</option><option :value="90">90 seconds</option><option :value="120">2 minutes</option><option :value="180">3 minutes</option></select></label><button class="button primary full" :disabled="busy||!current"><Icon name="Check"/>Save set & start rest</button></form></section>
<section class="card friendly-rest"><div class="section-title"><h3>{{rest>0?'Take a breath.':'Ready when you are.'}}</h3><Icon name="Clock"/></div><strong class="rest-digits">{{timeLabel(rest)}}</strong><small>{{app.active.pausedRest!==null?'Rest paused':rest>0?'Time to recover between sets':'Log a set to begin your rest timer'}}</small><div class="button-row"><button class="button secondary" :disabled="rest===0" @click="attempt(()=>restAction('pause'))"><Icon :name="app.active.pausedRest!==null?'Play':'Pause'" :size="15"/>{{app.active.pausedRest!==null?'Resume':'Pause'}}</button><button class="button secondary" @click="attempt(()=>restAction('add'))">+30 sec</button><button class="button secondary" :disabled="rest===0" @click="attempt(()=>restAction('skip'))">Skip</button></div></section>
<section class="card logged-sets"><h3>This exercise</h3><p v-if="!currentSets.length" class="muted">No sets recorded yet. Your entries will appear here.</p><div v-for="(set,i) in currentSets" :key="set.id" class="logged-set"><span class="set-tick"><Icon name="Check" :size="14"/></span><span>Set {{i+1}}</span><strong>{{set.reps}} reps <small>× {{set.kg}} kg</small></strong><button class="icon-button" :aria-label="'Remove set '+(i+1)" @click="attempt(async()=>{app.active!.sets=app.active!.sets.filter(s=>s.id!==set.id);await app.save()})"><Icon name="Trash2" :size="16"/></button></div><button v-if="position<app.active.exerciseIds.length-1" class="button primary full" @click="nextExercise(1)">Next exercise<Icon name="ArrowRight"/></button><button v-else class="button primary full" :disabled="!app.active.sets.length" @click="finishDialog?.showModal()">Review & finish<Icon name="Check"/></button><button class="text-link discard-link" @click="discardDialog?.showModal()">Discard this session</button></section></div></div>
</template>
<template v-else>
<nav class="training-tabs" aria-label="Training sections"><button :class="{active:tab==='explore'}" :aria-pressed="tab==='explore'" @click="tab='explore'"><Icon name="Search" :size="18"/>Explore</button><button :class="{active:tab==='builder'}" :aria-pressed="tab==='builder'" @click="tab='builder'"><Icon name="Dumbbell" :size="18"/>My workout <span>{{selected.length}}</span></button><button :class="{active:tab==='saved'}" :aria-pressed="tab==='saved'" @click="tab='saved'"><Icon name="Heart" :size="18"/>Saved <span>{{app.data.routines.length}}</span></button></nav>
<section v-show="tab==='explore'">
<div class="explore-toolbar card"><div class="location-selector" aria-label="Workout location"><button v-for="place in [{id:'all',name:'All workouts'},{id:'home',name:'At home'},{id:'gym',name:'At the gym'}]" :key="place.id" :class="{chosen:location===place.id}" :aria-pressed="location===place.id" @click="location=place.id">{{place.name}}</button></div><div v-if="location==='home'" class="home-equipment"><strong>What do you have at home?</strong><p class="input-help">Bodyweight is always included. Select your equipment to see only exercises you can set up. For a full home gym with barbells or machines, choose All workouts.</p><label v-for="item in homeEquipment" :key="item"><input type="checkbox" :value="item" v-model="available">{{item}}</label></div><label class="search-field"><Icon name="Search"/><input v-model="search" placeholder="Search an exercise or muscle…" aria-label="Search exercises"></label><div class="explore-filters"><label>Target muscle<select v-model="muscle"><option v-for="m in muscles" :key="m">{{m}}</option></select></label><label>Equipment<select v-model="equipment"><option v-for="group in equipmentGroups" :key="group">{{group}}</option></select></label><button class="button secondary favorite-filter" :class="{chosen:onlyFav}" :aria-pressed="onlyFav" @click="onlyFav=!onlyFav"><Icon name="Heart" :size="17"/>Favorites</button></div><details class="anatomy-disclosure"><summary>Explore muscles on the body guide</summary><div class="anatomy-content"><MuscleBody :selected="muscle"/><div><div class="muscle-buttons"><button v-for="m in muscles" :key="m" :class="{chosen:muscle===m}" @click="muscle=m">{{m}}</button></div><p class="input-help">Filters show primary targets; most movements also work other muscles.</p></div></div></details></div>
<div class="results-heading"><p><strong>{{filtered.length}}</strong> exercises <span>· tap View steps to learn a movement</span></p><button v-if="location!=='all'||search||muscle!=='All muscles'||equipment!=='All equipment'||onlyFav" class="text-link" @click="resetFilters">Reset filters</button></div>
<div class="exercise-card-grid"><article v-for="e in filtered" :key="e.id" class="exercise-tile" :class="{'is-added':selected.includes(e.id)}"><button class="tile-image-button" :aria-label="'View both positions for '+e.name" @click="detail=e"><ExerciseImage :exercise-id="e.id" :name="e.name" compact/><span class="two-position-label">2 positions</span></button><div class="tile-content"><div class="tile-heading"><div><span class="eyebrow">{{e.muscle}}</span><h3>{{e.name}}</h3></div><button class="icon-button" :aria-label="'Favorite '+e.name" :aria-pressed="app.data.favorites.includes(e.id)" :class="{chosen:app.data.favorites.includes(e.id)}" @click="attempt(()=>favorite(e.id))"><Icon name="Heart" :size="19"/></button></div><p class="equipment-label"><Icon name="Dumbbell" :size="14"/>{{e.equipment}}</p><div class="tile-actions"><button class="button secondary" @click="detail=e">View steps</button><button class="button" :class="selected.includes(e.id)?'added-button':'primary'" :aria-pressed="selected.includes(e.id)" @click="toggle(e.id)"><Icon :name="selected.includes(e.id)?'Check':'Plus'" :size="17"/>{{selected.includes(e.id)?'Added':'Add'}}</button></div></div></article></div>
<div v-if="!filtered.length" class="empty card"><Icon name="Search" :size="36"/><h3>No exercises match yet.</h3><p>Try a different muscle, equipment choice or search.</p><button class="button secondary" @click="resetFilters">Clear filters</button></div>
</section>
<section v-show="tab==='builder'" class="workout-builder card"><div class="section-title"><div><span class="eyebrow">MAKE IT YOURS</span><h2>Your workout</h2></div><span class="pill">{{selected.length}} exercises</span></div><div v-if="!selected.length" class="empty"><Icon name="Dumbbell" :size="40"/><h3>Let’s add your first exercise.</h3><p>Browse movements, see both positions, and tap Add.</p><button class="button primary" @click="tab='explore'">Explore exercises<Icon name="ArrowRight"/></button></div><template v-else><label>Give your workout a name<input v-model="routineName" maxlength="80" placeholder="e.g. Monday dumbbell session"></label><p class="input-help">Your draft saves automatically. Use the arrows to change exercise order.</p><div v-for="(id,i) in selected" :key="id" class="builder-row"><span class="builder-index">{{String(i+1).padStart(2,'0')}}</span><button class="builder-exercise" @click="detail=findExercise(id)"><strong>{{findExercise(id).name}}</strong><small>{{findExercise(id).equipment}} · View steps</small></button><div class="builder-order"><button :disabled="i===0" class="icon-button" :aria-label="'Move '+findExercise(id).name+' up'" @click="move(i,-1)">↑</button><button :disabled="i===selected.length-1" class="icon-button" :aria-label="'Move '+findExercise(id).name+' down'" @click="move(i,1)">↓</button></div><button class="icon-button" :aria-label="'Remove '+findExercise(id).name" @click="toggle(id)"><Icon name="Trash2" :size="17"/></button></div><div class="builder-actions"><button class="button secondary" @click="tab='explore'"><Icon name="Plus" :size="18"/>Add more</button><button class="button secondary" :disabled="busy" @click="attempt(saveRoutine)">Save as routine</button><button class="button primary" :disabled="busy" @click="attempt(start)"><Icon name="Play" :size="18"/>Start workout</button></div><p class="input-help">Choose your repetitions and weight during the session. Stop movements that cause pain.</p></template></section>
<section v-show="tab==='saved'"><div v-if="!app.data.routines.length" class="empty card"><Icon name="Heart" :size="40"/><h3>Your favorites, ready for next time.</h3><p>Build a workout and choose Save as routine to keep it here.</p><button class="button primary" @click="tab='builder'">Build a workout</button></div><div v-else class="routine-card-grid"><article v-for="r in app.data.routines" :key="r.id" class="card saved-routine-card"><div class="section-title"><Icon name="Dumbbell"/><button class="icon-button" :aria-label="'Delete routine '+r.name" @click="attempt(async()=>{if(windowConfirm('Delete saved routine “'+r.name+'”? Your completed workouts will stay.')){app.data.routines=app.data.routines.filter(x=>x.id!==r.id);await app.save()}})"><Icon name="Trash2" :size="18"/></button></div><h3>{{r.name}}</h3><p>{{r.exerciseIds.length}} exercises</p><ul><li v-for="id in r.exerciseIds.slice(0,4)" :key="id">{{findExercise(id).name}}</li><li v-if="r.exerciseIds.length>4">+ {{r.exerciseIds.length-4}} more</li></ul><button class="button primary full" @click="selected=[...r.exerciseIds];routineName=r.name;tab='builder'">Use this routine<Icon name="ArrowRight" :size="17"/></button></article></div></section>
<div v-if="selected.length" class="workout-dock"><div><span class="selection-icon"><Icon name="Dumbbell"/></span><p><strong>{{selected.length}} exercises selected</strong><small>{{app.error?'Draft not saved — retry above':app.saving?'Saving your draft…':'Your workout draft is saved on this device.'}}</small></p></div><button v-if="tab!=='builder'" class="button primary" @click="tab='builder';windowScrollTop()">Review workout<Icon name="ArrowRight" :size="18"/></button><button v-else class="button primary" :disabled="busy" @click="attempt(start)"><Icon name="Play" :size="17"/>Start workout</button></div>
</template>
<dialog v-if="detail" ref="dialog" class="modal card tutorial-dialog" aria-labelledby="exercise-title" @cancel.prevent="detail=null"><div class="tutorial-header"><div><span class="eyebrow">MOVEMENT GUIDE</span><h2 id="exercise-title">{{detail.name}}</h2><span class="muted">{{detail.muscle}} · {{detail.equipment}}</span></div><button class="icon-button" aria-label="Close movement guide" @click="detail=null"><Icon name="X"/></button></div><ExerciseImage :exercise-id="detail.id" :name="detail.name"/><div class="technique-note"><Icon name="Target" :size="19"/><p>{{detail.cue}}</p></div><details class="extra-instructions"><summary>More setup & technique details</summary><ol class="steps"><li v-for="step in detail.steps" :key="step">{{step}}</li></ol><p v-if="['Machines','Cable'].includes(detail.equipmentGroup)" class="input-help">Machine designs vary. Use the instructions on your actual machine for seat, pad, pin and safety adjustments.</p><p class="muted">Also works: {{detail.secondary}}. Use a comfortable range and stop if it hurts.</p></details><section class="exercise-alternatives"><h3>Other ways to train {{detail.muscle.toLowerCase()}}</h3><p class="input-help">Same main muscle, different equipment. Range, stability and effort vary; choose a fresh starting load for each exercise. Legs refers to knee-dominant exercises; hamstring isolation has its own category.</p><div class="form-grid"><label>Where?<select v-model="altLocation"><option value="all">Anywhere</option><option value="home">Home · my equipment</option><option value="gym">Gym</option></select></label><label>Equipment<select v-model="altEquipment"><option v-for="group in equipmentGroups" :key="group">{{group}}</option></select></label></div><p v-if="altLocation==='home'" class="input-help">Uses your home equipment choices in Explore. Bodyweight is always included.</p><p v-if="!alternatives.length" class="muted">No alternatives for these choices. Try another equipment type or Anywhere.</p><article v-for="e in alternatives" :key="e.id" class="alternative-row"><div><strong>{{e.name}}</strong><small>{{e.equipment}}</small><span class="pill">{{e.pattern===detail.pattern?'Similar movement':'Same main muscle'}}</span></div><div class="button-row"><button class="button secondary" @click="detail=e">View steps</button><button v-if="!app.active&&selected.includes(detail.id)" class="button secondary" @click="replaceWith(e.id)">Replace</button><button v-else-if="!app.active" class="button secondary" :disabled="selected.includes(e.id)" @click="toggle(e.id)">{{selected.includes(e.id)?'Added':'Add'}}</button></div></article></section><button v-if="!app.active" class="button primary full" @click="toggle(detail.id);detail=null"><Icon :name="selected.includes(detail.id)?'Check':'Plus'" :size="18"/>{{selected.includes(detail.id)?'Remove from workout':'Add to my workout'}}</button><button v-else class="button primary full" @click="detail=null">Back to workout</button></dialog>
<dialog ref="finishDialog" class="modal card confirmation-dialog"><h2>Finish this workout?</h2><p>{{app.active?.sets.length||0}} sets will be saved to your history.</p><p v-if="untouched" class="muted">{{untouched}} exercise(s) have no recorded sets. You can still finish now.</p><div class="button-row"><button class="button secondary" @click="finishDialog?.close()">Keep training</button><button class="button primary" :disabled="busy||!app.active?.sets.length" @click="attempt(finish)">Finish & save</button></div></dialog>
<dialog ref="discardDialog" class="modal card confirmation-dialog"><h2>Discard this session?</h2><p>Its logged sets will be removed. Your saved routines and previous workouts will stay.</p><div class="button-row"><button class="button secondary" @click="discardDialog?.close()">Keep training</button><button class="button danger" :disabled="busy" @click="attempt(discard)">Discard session</button></div></dialog>
</div></template>
